def transform(grid):
    h, w = len(grid), len(grid[0])
    rs = [r for r in range(h) if all(v == 8 for v in grid[r])]
    cs = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]

    def parts(n, separators):
        bounds = []
        start = 0
        for p in separators + [n]:
            if start < p:
                bounds.append((start, p))
            start = p + 1
        return bounds

    rows, cols = parts(h, rs), parts(w, cs)
    nr, nc = len(rows), len(cols)
    has = [[set() for _ in range(nc)] for _ in range(nr)]
    for i, (r0, r1) in enumerate(rows):
        for j, (c0, c1) in enumerate(cols):
            has[i][j] = {grid[r][c] for r in range(r0, r1)
                         for c in range(c0, c1)}

    # Each color's markers are joined by straight horizontal/vertical spans
    # whenever they share a block row or column.
    mask2 = set()
    mask3 = set()
    for color, mask in ((2, mask2), (3, mask3)):
        points = [(i, j) for i in range(nr) for j in range(nc)
                  if color in has[i][j]]
        for i, j in points:
            same_row = [q for p, q in points if p == i]
            same_col = [p for p, q in points if q == j]
            for q in same_row:
                for x in range(min(j, q), max(j, q) + 1):
                    mask.add((i, x))
            for p in same_col:
                for x in range(min(i, p), max(i, p) + 1):
                    mask.add((x, j))

    out = [row[:] for row in grid]
    for i, (r0, r1) in enumerate(rows):
        for j, (c0, c1) in enumerate(cols):
            color = 6 if (i, j) in mask2 and (i, j) in mask3 else (
                2 if (i, j) in mask2 else (3 if (i, j) in mask3 else None))
            if color is not None:
                for r in range(r0, r1):
                    for c in range(c0, c1):
                        out[r][c] = color
    return out
